import{_ as a,o as t,c as n,a3 as i}from"./chunks/framework.DQ-7HQaQ.js";const u=JSON.parse('{"title":"Delivery roadmap: harvest, prove, then extend","description":"","frontmatter":{},"headers":[],"relativePath":"project/roadmap.md","filePath":"project/roadmap.md","lastUpdated":1794433168000}'),r={name:"project/roadmap.md"};function o(s,e,l,d,c,p){return t(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="delivery-roadmap-harvest-prove-then-extend" tabindex="-1">Delivery roadmap: harvest, prove, then extend <a class="header-anchor" href="#delivery-roadmap-harvest-prove-then-extend" aria-label="Permalink to &quot;Delivery roadmap: harvest, prove, then extend&quot;">​</a></h1><p><strong>Status: implementation plan, not delivered runtime.</strong> Each slice is deliberately bounded. A slice closes only against its own code, tests and evidence; the documentation exercises do not close application acceptance.</p><p>The source audit changed the ordering: durable job/state contracts should precede the live chat shell. We already have relevant historical Rust code, so we should not first create an in-memory system that later needs replacement.</p><h2 id="dependency-map" tabindex="-1">Dependency map <a class="header-anchor" href="#dependency-map" aria-label="Permalink to &quot;Dependency map&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>S0 · evidence and contract review</span></span>
<span class="line"><span>  → S1 · clean workspace and durable kernel</span></span>
<span class="line"><span>  → S2 · sources, claims and identity proposals</span></span>
<span class="line"><span>  → S3 · reviewed atomic publication</span></span>
<span class="line"><span>  → S4 · evidence retrieval and evaluation</span></span>
<span class="line"><span>  → S5 · streaming research interface</span></span>
<span class="line"><span>  → S6 · portable export and native-worker boundary</span></span>
<span class="line"><span>  → S7 · verified QA release and bounded public demonstration</span></span></code></pre></div><p>Independent workstreams: portfolio DNS and documentation Pages activation. Neither authorizes changing the application server. Native acceleration research may proceed separately, but no backend enters a release without the common contract tests.</p><h2 id="s0-·-approve-what-we-are-reusing" tabindex="-1">S0 · Approve what we are reusing <a class="header-anchor" href="#s0-·-approve-what-we-are-reusing" aria-label="Permalink to &quot;S0 · Approve what we are reusing&quot;">​</a></h2><p><strong>Inputs:</strong> <a href="./../reuse/source-audit">source audit</a>, <a href="./../reuse/harvest-plan">harvest plan</a>, requirements and twelve-factor matrix.</p><p><strong>Deliver:</strong> applicable source-license/notice review; exact donor symbols and dependency inventory; versioned contract sketches; synthetic fixture set; selected application toolchain and supported initial platform. Distinguish current rebuild, historical daemon and owner-only source.</p><p><strong>Exit:</strong> R-15/A-15 evidence; no private dependency needed for public CI. Record accepted architecture decisions, including hosted store separation and local exceptions. Stop if reuse rights, source identity or an authority boundary remain unclear. This documentation update advances S0; it does not complete the whole gate.</p><h2 id="s1-·-clean-workspace-and-durable-kernel" tabindex="-1">S1 · Clean workspace and durable kernel <a class="header-anchor" href="#s1-·-clean-workspace-and-durable-kernel" aria-label="Permalink to &quot;S1 · Clean workspace and durable kernel&quot;">​</a></h2><p><strong>Depends on:</strong> S0. <strong>Donors:</strong> H-01 job kernel, H-02 event log; C-03 contract shapes.</p><p><strong>Deliver:</strong> minimal Cargo workspace, typed IDs/configuration, schema migrations, transaction-owned store commands, plan validation, idempotent job creation, bounded task claiming and scoped event replay. Separate domain logic from Axum/SQLite adapters. Public CI builds without model keys.</p><p><strong>Exit:</strong> A-01/A-06/A-10; TF-01/02/03/06/08. Race two independent clients; reject expired and stale-epoch results even with the same worker name; detect corrupt stored JSON; roll back state and its event together. A skipped required validation stage cannot advance publication. Do not begin a bespoke broker or generic workflow-builder UI.</p><h2 id="s2-·-evidence-claims-and-identity-proposals" tabindex="-1">S2 · Evidence, claims and identity proposals <a class="header-anchor" href="#s2-·-evidence-claims-and-identity-proposals" aria-label="Permalink to &quot;S2 · Evidence, claims and identity proposals&quot;">​</a></h2><p><strong>Depends on:</strong> S1. <strong>Donors:</strong> H-03 candidate lifecycle; owner-reviewed E extraction/artifact steps.</p><p><strong>Deliver:</strong> immutable source artifacts and acquisition records, typed text/media locations, mentions, stable entity IDs, many-to-many aliases, qualified claims/assertions and a review queue. Use deterministic synthetic extractors first.</p><p><strong>Exit:</strong> A-02/A-03/A-04/A-05. Include two people with one name, one incident with multiple aliases, a vessel/incident naming trap, a copied report and contradictory testimony. A new source cannot create a new canonical entity solely because the candidate hash changed. Prove a merge can be reversed without deleting the previous decision. No automatic name-only canonical merge.</p><h2 id="s3-·-reviewed-atomic-publication" tabindex="-1">S3 · Reviewed, atomic publication <a class="header-anchor" href="#s3-·-reviewed-atomic-publication" aria-label="Permalink to &quot;S3 · Reviewed, atomic publication&quot;">​</a></h2><p><strong>Depends on:</strong> S2. <strong>Donors:</strong> H-03 promotion records, E staging ideas; replace their assumptions where necessary.</p><p><strong>Deliver:</strong> immutable proposal bundle, review bound to its digest and base revision, authenticated approval command, all-endpoint validation, publication transaction and scoped event. Create an explicit published revision; publication is not a boolean sprinkled across unrelated tables.</p><p><strong>Exit:</strong> A-06/A-14 and relevant A-05/A-11. Inject failures between every durable write category. Check no half-published entity/edge/evidence/revision/event survives. Reject stale review, changed proposal, hidden endpoint and cross-library approval. The <a href="./../engineering/examples#atomic-publication">publication lab</a> specifies a small subset, not the full implementation.</p><h2 id="s4-·-retrieval-that-can-expose-its-evidence" tabindex="-1">S4 · Retrieval that can expose its evidence <a class="header-anchor" href="#s4-·-retrieval-that-can-expose-its-evidence" aria-label="Permalink to &quot;S4 · Retrieval that can expose its evidence&quot;">​</a></h2><p><strong>Depends on:</strong> S3. <strong>Donors:</strong> corpus/vector staging patterns, not a claim that the lexical placeholder is a semantic index.</p><p><strong>Deliver:</strong> lexical baseline, graph filtering/expansion, immutable citation packets, optional compatible embedding adapter and a small reviewed evaluation set. Filter access before retrieval, ranking and caching. Record library revision and embedding-space identity.</p><p><strong>Exit:</strong> A-02/A-05/A-08/A-11. Evaluate false matches, unresolved identities and evidence relevance against fixed fixtures. Missing compatible query embeddings produce a declared lexical/graph-only mode. Public results must not leak hidden identifiers, source text, facets or cached private evidence. Numerical quality targets are chosen from a measured baseline, not invented in this plan.</p><h2 id="s5-·-streaming-research-interface" tabindex="-1">S5 · Streaming research interface <a class="header-anchor" href="#s5-·-streaming-research-interface" aria-label="Permalink to &quot;S5 · Streaming research interface&quot;">​</a></h2><p><strong>Depends on:</strong> S1, S3 and S4. <strong>Donors:</strong> C-01 gateway adapter/batching, W-01 browser protocol/session behavior, C-03 projections.</p><p><strong>Deliver:</strong> Svelte chat/evidence/jobs/review views; Rust API; durable run admission; normalized model outcomes; bounded SSE delivery and explicit cancellation. Provider execution belongs to a leased bounded worker; an API connection is not the owner of durable conversation truth.</p><p><strong>Exit:</strong> A-09/A-11/A-12; TF-06/07/09. Test all byte boundaries, premature EOF, refusal, length-limited output, slow clients, disconnect/reconnect, server termination and account changes through real HTTPS. An interrupted paid generation is not silently rerun. A citation opens the exact pinned evidence, including after a newer library is published.</p><h2 id="s6-·-portable-library-and-capability-substitution" tabindex="-1">S6 · Portable library and capability substitution <a class="header-anchor" href="#s6-·-portable-library-and-capability-substitution" aria-label="Permalink to &quot;S6 · Portable library and capability substitution&quot;">​</a></h2><p><strong>Depends on:</strong> S3; interface inspection from S5. <strong>Donors:</strong> artifact manifests and host-worker design, reviewed separately from implementations.</p><p><strong>Deliver:</strong> package format v1, supported consistent snapshot/export, safe import/preflight, integrity verification, public-only export construction, worker readiness/permissions and one minimal native worker contract demonstration.</p><p><strong>Exit:</strong> A-07/A-08 and TF-04/10/12. Open a Mac-created package on Linux without Apple plugins. Tampered/missing objects fail validation; unbound inputs stay disabled. Inspect the exported bytes and indexes for draft/private material. No credentials, executable auto-start, absolute home paths or opaque device handles are needed to read evidence. Selectively importing a historical library is not copying an entire private live database.</p><h2 id="s7-·-verified-hosted-release" tabindex="-1">S7 · Verified hosted release <a class="header-anchor" href="#s7-·-verified-hosted-release" aria-label="Permalink to &quot;S7 · Verified hosted release&quot;">​</a></h2><p><strong>Depends on:</strong> S1–S6 plus a separately verified host inventory. <strong>Donors:</strong> hosting studio and chat release practices as operational references.</p><p><strong>Deliver:</strong> isolated QA, immutable per-platform artifacts, release manifest, explicit production approval, usage/admission limits, off-host backups and restore/rollback procedures. Only approved public data enters the demonstration. No heavy inference placement is assumed from an old Droplet inventory.</p><p><strong>Exit:</strong> all applicable A-01–A-15 and TF-01–TF-12 have actual evidence or an explicitly accepted local-profile exception. Test production-path proxy streaming, empty-disk API replacement, schema compatibility and restore into an isolated target. A failed deployment must not require deleting the only library or production volume. Pages serves documentation, not this application.</p><h2 id="work-packaging-and-review" tabindex="-1">Work packaging and review <a class="header-anchor" href="#work-packaging-and-review" aria-label="Permalink to &quot;Work packaging and review&quot;">​</a></h2><p>Each implementation issue contains: slice and requirement IDs, pinned donor symbols, proposed target module, scope/non-goals, tests, dependencies, public/private boundary and rollback considerations. Link a test-plan issue, atomic commits, PR and command receipts. A merge should not close a requirement whose evidence is still only a design paragraph.</p><p>Suggested first issue after S0: <strong>Extract DAG validation and idempotent job creation with transactional events.</strong> Its non-goals are model calls, a frontend, graph inference and live deployment. Follow it with lease fencing/scoped replay, then the evidence schema. Keep those changes separately reviewable.</p><h2 id="earlier-roadmap-reconciliation" tabindex="-1">Earlier roadmap reconciliation <a class="header-anchor" href="#earlier-roadmap-reconciliation" aria-label="Permalink to &quot;Earlier roadmap reconciliation&quot;">​</a></h2><p>This S-series supersedes the earlier G-series ordering, not its goals. G0/G1 map to S0; G5 moves forward into S1; G3 maps to S2/S3; G4 to S4/S6; G2 to S5; G6/G7 to S7. Earlier architecture and research pages remain clearly labelled reference material.</p><h2 id="is373-demonstration" tabindex="-1">IS373 demonstration <a class="header-anchor" href="#is373-demonstration" aria-label="Permalink to &quot;IS373 demonstration&quot;">​</a></h2><p>A learner predicts a failure, reproduces it, explains the relevant source, proposes a bounded repair and identifies what the test does not prove. The final walkthrough imports conflicting reports, reviews identities, publishes a revision, streams a cited answer and reopens the library on a machine with a capability missing. This is an instructor example, not a new grading policy.</p>`,45)])])}const m=a(r,[["render",o]]);export{u as __pageData,m as default};
